__d(function(g,r,i,a,m,e,d){"use strict";Object.defineProperty(e,'__esModule',{value:!0}),Object.defineProperty(e,"professionnelsDocument",{enumerable:!0,get:function(){return t}});var n=r(d[0]),s=r(d[1]);const t=(0,n.publishedDocument)({id:"professionnels",slug:"professionnels",title:"Conditions g\xe9n\xe9rales \u2014 Professionnels partenaires",shortTitle:"Conditions Pro",sections:[{heading:"1. Objet",paragraphs:[`Les pr\xe9sentes Conditions g\xe9n\xe9rales (\xab Conditions Pro \xbb) r\xe9gissent la relation entre ${s.LEGAL_OPERATOR_NAME}, \xe9diteur et exploitant de ${s.LEGAL_TRADE_NAME}, et tout professionnel utilisant le Service afin de r\xe9f\xe9rencer un ou plusieurs \xe9tablissements et de proposer des produits \xe0 des consommateurs.`,`${s.LEGAL_TRADE_NAME} est une plateforme num\xe9rique de mise en relation et de commande de produits alimentaires \xe0 emporter en click & collect.`,"Croki fournit notamment des outils de r\xe9f\xe9rencement, de pr\xe9sentation du catalogue, de r\xe9ception et de suivi des commandes, de paiement, de gestion op\xe9rationnelle et d\u2019interaction avec les Clients.","Croki ne fournit pas de service de livraison.","Les pr\xe9sentes Conditions Pro constituent le cadre contractuel g\xe9n\xe9ral applicable au Professionnel, sous r\xe9serve de tout accord particulier \xe9crit conclu avec FOODTECH SOLUTIONS."]},{heading:"2. D\xe9finitions",paragraphs:[`\xab Croki \xbb ou \xab Service \xbb d\xe9signe la plateforme ${s.LEGAL_TRADE_NAME}, \xe9dit\xe9e et exploit\xe9e par ${s.LEGAL_OPERATOR_NAME}.`,"\xab Professionnel \xbb d\xe9signe toute personne physique ou morale agissant dans le cadre de son activit\xe9 professionnelle et autoris\xe9e \xe0 utiliser Croki pour proposer ses produits.","\xab \xc9tablissement \xbb d\xe9signe un point de vente exploit\xe9 par le Professionnel et r\xe9f\xe9renc\xe9 sur Croki, notamment un foodtruck ou autre \xe9tablissement alimentaire compatible avec le Service.","\xab Client \xbb d\xe9signe un consommateur utilisant Croki pour commander des produits aupr\xe8s d\u2019un Professionnel.","\xab Commande \xbb d\xe9signe la commande de produits effectu\xe9e par un Client aupr\xe8s du Professionnel au moyen de Croki.","\xab Catalogue \xbb d\xe9signe l\u2019ensemble des produits, formules, options, prix, descriptions, allerg\xe8nes, photographies et informations commerciales renseign\xe9s par le Professionnel.","\xab Compte Pro \xbb d\xe9signe le compte permettant au Professionnel ou \xe0 ses utilisateurs autoris\xe9s d\u2019acc\xe9der aux fonctionnalit\xe9s professionnelles de Croki."]},{heading:"3. \xc9ligibilit\xe9 du Professionnel",paragraphs:["L\u2019utilisation de Croki en qualit\xe9 de Professionnel est r\xe9serv\xe9e aux personnes exer\xe7ant l\xe9galement une activit\xe9 professionnelle compatible avec la vente des produits propos\xe9s sur la plateforme.","Le Professionnel d\xe9clare disposer de la capacit\xe9 juridique, des immatriculations, d\xe9clarations, licences, autorisations, assurances et qualifications n\xe9cessaires \xe0 son activit\xe9 lorsque celles-ci sont requises.","Il s\u2019engage \xe0 maintenir ces conditions pendant toute la dur\xe9e de son utilisation de Croki.","FOODTECH SOLUTIONS peut demander les justificatifs raisonnablement n\xe9cessaires afin de v\xe9rifier l\u2019identit\xe9, la qualit\xe9 professionnelle, l\u2019activit\xe9 ou le respect des conditions d\u2019acc\xe8s \xe0 Croki."]},{heading:"4. Identification et v\xe9rification du Professionnel",paragraphs:["Le Professionnel fournit \xe0 Croki des informations exactes, compl\xe8tes et \xe0 jour permettant son identification ainsi que celle de son entreprise et de ses \xe9tablissements.","Ces informations peuvent notamment comprendre la d\xe9nomination ou le nom professionnel, la forme juridique, l\u2019adresse, les coordonn\xe9es, le num\xe9ro SIREN ou SIRET, le num\xe9ro de TVA lorsqu\u2019il existe, les informations fiscales requises ainsi que l\u2019identit\xe9 de la personne habilit\xe9e \xe0 agir pour le Professionnel.","Le Professionnel s\u2019engage \xe0 signaler toute modification affectant ces informations.","FOODTECH SOLUTIONS peut effectuer ou faire effectuer les v\xe9rifications rendues n\xe9cessaires par la loi, la r\xe9glementation, les r\xe8gles de s\xe9curit\xe9 du Service ou les exigences du prestataire de paiement.","Lorsque certaines informations ou v\xe9rifications sont indispensables \xe0 l\u2019utilisation l\xe9gale du Service, Croki peut emp\xeacher l\u2019activation ou restreindre certaines fonctionnalit\xe9s jusqu\u2019\xe0 leur fourniture ou leur validation."]},{heading:"5. Compte de paiement Stripe",paragraphs:["La r\xe9ception de paiements au moyen de Croki n\xe9cessite l\u2019utilisation d\u2019un compte de paiement compatible avec l\u2019infrastructure Stripe Connect utilis\xe9e par le Service.","Le Professionnel doit accomplir les v\xe9rifications d\u2019identit\xe9, de repr\xe9sentation, bancaires et r\xe9glementaires demand\xe9es par Stripe.","L\u2019activation du service de commande peut \xeatre conditionn\xe9e \xe0 la capacit\xe9 effective du compte Stripe du Professionnel \xe0 recevoir et traiter les paiements.","Stripe demeure responsable de ses propres services de paiement conform\xe9ment aux conditions applicables entre Stripe et le Professionnel.","FOODTECH SOLUTIONS n\u2019est pas un \xe9tablissement bancaire et ne fournit pas elle-m\xeame au Professionnel un compte bancaire ou un service r\xe9glement\xe9 de paiement."]},{heading:"6. Cr\xe9ation et activation d\u2019un \xc9tablissement",paragraphs:["La cr\xe9ation d\u2019un Compte Pro ou l\u2019envoi d\u2019une demande de r\xe9f\xe9rencement ne rend pas automatiquement l\u2019\xc9tablissement visible ou disponible \xe0 la commande.","FOODTECH SOLUTIONS peut v\xe9rifier les informations communiqu\xe9es avant l\u2019activation de l\u2019\xc9tablissement.","L\u2019\xc9tablissement devient accessible aux fonctionnalit\xe9s publiques et commerciales correspondantes lorsque son statut permet son activation et que les conditions techniques, r\xe9glementaires et de paiement n\xe9cessaires sont satisfaites.","Un refus d\u2019activation doit reposer sur un motif li\xe9 notamment aux pr\xe9sentes Conditions Pro, \xe0 l\u2019\xe9ligibilit\xe9 du Professionnel, \xe0 la conformit\xe9 du contenu ou de l\u2019activit\xe9, \xe0 une obligation l\xe9gale ou r\xe9glementaire, \xe0 la s\xe9curit\xe9 ou au fonctionnement du Service."]},{heading:"7. Responsabilit\xe9 du Professionnel sur son activit\xe9",paragraphs:["Le Professionnel agit en son nom et pour son propre compte dans la vente des produits qu\u2019il propose aux Clients.","Il demeure seul responsable de l\u2019exploitation de son activit\xe9, de son \xe9tablissement, de ses produits, de leur pr\xe9paration et de leur remise aux Clients, sous r\xe9serve des obligations propres \xe0 FOODTECH SOLUTIONS concernant l\u2019exploitation de Croki.","La relation avec Croki n\u2019a pas pour effet de cr\xe9er entre FOODTECH SOLUTIONS et le Professionnel une relation de salariat, de soci\xe9t\xe9 commune ou de repr\xe9sentation g\xe9n\xe9rale.","Le Professionnel reste libre d\u2019organiser son activit\xe9 dans le respect de ses obligations contractuelles et l\xe9gales."]},{heading:"8. Obligations sanitaires et alimentaires",paragraphs:["Le Professionnel est responsable du respect de l\u2019ensemble des r\xe8gles applicables \xe0 la pr\xe9paration, \xe0 la conservation, \xe0 la manipulation, au transport \xe9ventuel interne \xe0 son activit\xe9 et \xe0 la commercialisation des denr\xe9es alimentaires.","Il lui appartient notamment de respecter les obligations applicables en mati\xe8re d\u2019hygi\xe8ne alimentaire, de s\xe9curit\xe9 sanitaire, de tra\xe7abilit\xe9, de retrait ou rappel de produits et d\u2019information des consommateurs.","Le Professionnel s\u2019engage \xe0 ne proposer sur Croki que des produits qu\u2019il est l\xe9galement autoris\xe9 \xe0 commercialiser.","Il informe Croki dans les meilleurs d\xe9lais de tout incident sanitaire, rappel, retrait, fermeture administrative ou situation susceptible d\u2019affecter les Commandes ou la s\xe9curit\xe9 des Clients."]},{heading:"9. Allerg\xe8nes et composition",paragraphs:["Le Professionnel est responsable de l\u2019identification, de l\u2019exactitude et de l\u2019actualisation des informations obligatoires relatives aux allerg\xe8nes et \xe0 la composition des produits qu\u2019il commercialise.","Croki met \xe0 disposition des fonctionnalit\xe9s permettant de structurer et pr\xe9senter ces informations aux Clients.","Le Professionnel ne doit pas d\xe9clarer un produit comme exempt d\u2019un allerg\xe8ne lorsqu\u2019il ne dispose pas des informations permettant de l\u2019affirmer.","Lorsqu\u2019une information doit encore \xeatre v\xe9rifi\xe9e, le Professionnel doit utiliser l\u2019\xe9tat ou la formulation appropri\xe9e propos\xe9e par Croki et ne pas fournir une information susceptible d\u2019induire le consommateur en erreur.","Le Professionnel reste responsable des risques de contamination crois\xe9e r\xe9sultant de sa pr\xe9paration, de son environnement de travail et de ses proc\xe9d\xe9s."]},{heading:"10. Catalogue et contenus",paragraphs:["Le Professionnel est responsable des informations qu\u2019il publie sur Croki, notamment les d\xe9nominations, descriptions, photographies, prix, quantit\xe9s, options, formules, disponibilit\xe9s, allerg\xe8nes, horaires, lieux et informations commerciales.","Ces informations doivent \xeatre exactes, loyales, compr\xe9hensibles, \xe0 jour et conformes \xe0 la r\xe9glementation applicable.","Le Professionnel ne doit pas publier de contenu trompeur, illicite, contrefaisant, discriminatoire ou portant atteinte aux droits de tiers.","Les photographies et autres contenus utilis\xe9s doivent appartenir au Professionnel ou \xeatre utilis\xe9s avec les autorisations n\xe9cessaires."]},{heading:"11. Prix propos\xe9s aux Clients",paragraphs:["Le Professionnel d\xe9termine les prix des produits qu\u2019il propose sur Croki, sous r\xe9serve des r\xe8gles l\xe9gales applicables.","Les prix destin\xe9s aux consommateurs doivent \xeatre renseign\xe9s conform\xe9ment aux r\xe8gles d\u2019affichage applicables et permettre \xe0 Croki de pr\xe9senter correctement le prix d\xfb par le Client.","Le Professionnel reste responsable de la fiscalit\xe9 et du taux de TVA applicables aux produits qu\u2019il commercialise.","Toute modification de prix ne produit effet que pour les Commandes futures. Elle ne modifie pas r\xe9troactivement le prix d\u2019une Commande d\xe9j\xe0 accept\xe9e."]},{heading:"12. Horaires, lieux et disponibilit\xe9",paragraphs:["Le Professionnel renseigne et maintient \xe0 jour les informations relatives \xe0 ses horaires, lieux de retrait, p\xe9riodes d\u2019ouverture, capacit\xe9s et disponibilit\xe9s.","Il doit fermer ou mettre en pause son service lorsqu\u2019il n\u2019est pas en mesure d\u2019accepter ou d\u2019ex\xe9cuter normalement de nouvelles Commandes.","Le lieu de retrait enregistr\xe9 pour une Commande constitue la r\xe9f\xe9rence pr\xe9sent\xe9e au Client pour cette Commande.","Le Professionnel est responsable de l\u2019exactitude du lieu et des informations op\xe9rationnelles qu\u2019il renseigne."]},{heading:"13. R\xe9ception des Commandes",paragraphs:["Croki transmet au Professionnel les demandes de Commande r\xe9pondant aux conditions techniques et de paiement pr\xe9vues par le Service.","Le Professionnel doit examiner chaque demande et l\u2019accepter ou la refuser dans le d\xe9lai affich\xe9 ou communiqu\xe9 par Croki.","Une Commande demeurant sans r\xe9ponse jusqu\u2019\xe0 l\u2019expiration du d\xe9lai applicable peut \xeatre automatiquement expir\xe9e.","Le Professionnel ne doit pas commencer la pr\xe9paration sur la seule base d\u2019une demande qui n\u2019a pas encore \xe9t\xe9 accept\xe9e et dont le paiement n\u2019a pas atteint l\u2019\xe9tat permettant sa pr\xe9paration."]},{heading:"14. Acceptation d\u2019une Commande",paragraphs:["L\u2019acceptation par le Professionnel confirme qu\u2019il est en mesure de pr\xe9parer et remettre les produits command\xe9s conform\xe9ment aux informations pr\xe9sent\xe9es au Client.","L\u2019acceptation entra\xeene la formation de la vente entre le Professionnel et le Client selon les conditions applicables \xe0 la Commande.","Elle d\xe9clenche ou permet la finalisation des op\xe9rations de paiement pr\xe9vues par Croki.","Le Professionnel doit v\xe9rifier avant acceptation que les produits command\xe9s sont disponibles et qu\u2019il dispose de la capacit\xe9 n\xe9cessaire pour les pr\xe9parer."]},{heading:"15. Refus et expiration",paragraphs:["Le Professionnel peut refuser une Commande lorsqu\u2019il n\u2019est pas en mesure de l\u2019ex\xe9cuter, notamment en cas d\u2019indisponibilit\xe9 d\u2019un produit, de capacit\xe9 insuffisante, d\u2019incident technique ou de fermeture impr\xe9vue.","Le Professionnel ne doit pas utiliser le refus d\u2019une Commande de mani\xe8re discriminatoire ou contraire \xe0 la loi.","Lorsqu\u2019une Commande est refus\xe9e ou expire avant acceptation, la vente avec le Client n\u2019est pas form\xe9e et les op\xe9rations de paiement correspondantes sont annul\xe9es, lib\xe9r\xe9es ou rembours\xe9es selon leur \xe9tat."]},{heading:"16. Pr\xe9paration et retrait",paragraphs:["Apr\xe8s acceptation et lorsque le paiement permet la pr\xe9paration, le Professionnel pr\xe9pare la Commande conform\xe9ment aux informations communiqu\xe9es au Client.","Il utilise les statuts propos\xe9s par Croki afin d\u2019indiquer de mani\xe8re fid\xe8le l\u2019avancement de la Commande, notamment lorsqu\u2019elle est en pr\xe9paration ou pr\xeate \xe0 \xeatre retir\xe9e.","Le Professionnel remet la Commande au Client ou \xe0 la personne l\xe9gitimement habilit\xe9e \xe0 la r\xe9cup\xe9rer.","Les m\xe9canismes de code ou d\u2019identification propos\xe9s par Croki sont destin\xe9s \xe0 faciliter la correspondance entre la Commande et son retrait ; le Professionnel conserve l\u2019obligation d\u2019exercer les v\xe9rifications raisonnables n\xe9cessaires."]},{heading:"17. Paiement des ventes",paragraphs:["Les paiements des produits sont trait\xe9s au moyen de Stripe Connect.","Les sommes dues au Professionnel au titre des ventes sont trait\xe9es sur son environnement Stripe connect\xe9, sous d\xe9duction des commissions Croki, frais Stripe et autres montants l\xe9galement ou contractuellement applicables.","Les d\xe9lais de versement vers le compte bancaire du Professionnel d\xe9pendent notamment de Stripe, des param\xe8tres du compte et du syst\xe8me bancaire.","Le Professionnel doit maintenir des coordonn\xe9es bancaires valides et un compte Stripe en \xe9tat de fonctionner."]},{heading:"18. R\xe9mun\xe9ration de Croki",paragraphs:[`En contrepartie du service fourni au Professionnel, ${s.LEGAL_OPERATOR_NAME} per\xe7oit une commission actuellement fix\xe9e \xe0 3 % HT du montant des produits faisant l\u2019objet de chaque Commande accept\xe9e et encaiss\xe9e, hors Frais de service factur\xe9s s\xe9par\xe9ment au Client.`,"La TVA applicable \xe0 la commission Croki est ajout\xe9e conform\xe9ment au taux l\xe9gal en vigueur.","La commission est pr\xe9lev\xe9e automatiquement dans le cadre du traitement du paiement lorsque l\u2019infrastructure de paiement le permet.","Le bar\xe8me applicable \xe0 une Commande est celui port\xe9 \xe0 la connaissance du Professionnel avant cette Commande.","Toute \xe9volution future de la commission ou de sa m\xe9thode de calcul constitue une modification des conditions \xe9conomiques et suit les r\xe8gles de notification pr\xe9vues par les pr\xe9sentes Conditions Pro."]},{heading:"19. Frais de service factur\xe9s au Client",paragraphs:["Croki facture actuellement au Client un Frais de service distinct de 0,50 \u20ac TTC par Commande lorsque ce frais est applicable.","Ce Frais de service r\xe9mun\xe8re le service fourni par FOODTECH SOLUTIONS au Client et ne constitue pas une somme revenant au Professionnel au titre de la vente des produits.","Il est pr\xe9sent\xe9 s\xe9par\xe9ment au Client avant la validation de sa Commande.","Le Frais de service Client n\u2019entre pas dans l\u2019assiette de la commission de 3 % due par le Professionnel."]},{heading:"20. Frais Stripe",paragraphs:["Les frais factur\xe9s par Stripe au titre du traitement du paiement des produits sont support\xe9s par le Professionnel lorsque ces frais sont imput\xe9s \xe0 son compte Stripe conform\xe9ment au fonctionnement de Stripe Connect utilis\xe9 par Croki.","Les frais li\xe9s au traitement du Frais de service propre \xe0 Croki sont support\xe9s par FOODTECH SOLUTIONS.","Les tarifs et conditions propres de Stripe peuvent \xe9voluer ind\xe9pendamment de FOODTECH SOLUTIONS."]},{heading:"21. Facturation entre FOODTECH SOLUTIONS et le Professionnel",paragraphs:["FOODTECH SOLUTIONS \xe9tablit les documents de facturation relatifs aux commissions et autres sommes qui lui sont dues conform\xe9ment aux r\xe8gles fiscales et comptables applicables.","Lorsque les commissions ont d\xe9j\xe0 \xe9t\xe9 automatiquement pr\xe9lev\xe9es lors du traitement des Commandes, la facture correspondante peut mentionner les montants d\xe9j\xe0 r\xe9gl\xe9s et un solde restant d\xfb nul.","Les factures peuvent r\xe9capituler les commissions correspondant aux Commandes r\xe9alis\xe9es sur la p\xe9riode concern\xe9e.","L\u2019outil utilis\xe9 par FOODTECH SOLUTIONS pour produire ou conserver ses factures est sans incidence sur les obligations comptables propres du Professionnel."]},{heading:"22. Obligations fiscales du Professionnel",paragraphs:["Le Professionnel reste seul responsable de ses obligations fiscales, comptables, sociales et d\xe9claratives li\xe9es \xe0 son activit\xe9 et aux ventes r\xe9alis\xe9es aupr\xe8s des Clients.","Il demeure notamment responsable de la d\xe9termination, de la d\xe9claration et du paiement de la TVA et des autres pr\xe9l\xe8vements applicables \xe0 ses ventes.","Croki ne constitue pas le logiciel comptable du Professionnel et ne se substitue pas \xe0 son expert-comptable, son conseil fiscal ou l\u2019administration comp\xe9tente."]},{heading:"23. DAC7 et obligations d\xe9claratives des plateformes",paragraphs:["FOODTECH SOLUTIONS peut \xeatre tenue, en qualit\xe9 d\u2019op\xe9rateur de plateforme, de collecter, v\xe9rifier, conserver et transmettre \xe0 l\u2019administration fiscale certaines informations relatives aux Professionnels et aux op\xe9rations r\xe9alis\xe9es au moyen de Croki.","Le Professionnel s\u2019engage \xe0 fournir les informations et justificatifs n\xe9cessaires \xe0 l\u2019ex\xe9cution de ces obligations, notamment lorsqu\u2019ils concernent son identit\xe9, son adresse, sa r\xe9sidence fiscale, son num\xe9ro d\u2019identification fiscale, ses op\xe9rations ou les sommes per\xe7ues.","Croki peut rappeler au Professionnel les informations d\xe9clar\xe9es ou transmises lorsque la r\xe9glementation l\u2019exige.","Le Professionnel reste responsable de ses propres d\xe9clarations fiscales et de l\u2019imposition des revenus ou chiffres d\u2019affaires issus de son activit\xe9."]},{heading:"24. Remboursements",paragraphs:["Lorsqu\u2019un remboursement d\u2019une Commande est justifi\xe9, Croki peut permettre son traitement au moyen de l\u2019infrastructure de paiement utilis\xe9e.","Le Professionnel coop\xe8re avec Croki pour traiter les demandes li\xe9es notamment \xe0 une Commande non ex\xe9cut\xe9e, incorrecte, indisponible ou faisant l\u2019objet d\u2019un incident.","Un remboursement peut avoir un impact sur les sommes revenant au Professionnel et, lorsque les conditions \xe9conomiques applicables le pr\xe9voient, sur la commission correspondante.","Croki ne doit pas imposer au Professionnel la charge d\u2019une somme dont la responsabilit\xe9 incombe l\xe9galement \xe0 FOODTECH SOLUTIONS."]},{heading:"25. Contestations de paiement et fraude",paragraphs:["Le Professionnel coop\xe8re avec Croki et Stripe en cas de fraude pr\xe9sum\xe9e, contestation bancaire, demande de preuve ou incident relatif \xe0 une Commande.","Il conserve et fournit, lorsque cela est raisonnablement n\xe9cessaire, les informations permettant d\u2019\xe9tablir la pr\xe9paration ou la remise de la Commande.","Les cons\xe9quences financi\xe8res d\u2019une contestation ou d\u2019une fraude sont d\xe9termin\xe9es selon l\u2019origine de l\u2019incident, les conditions applicables au paiement et les responsabilit\xe9s respectives des parties.","Aucune clause des pr\xe9sentes Conditions ne transf\xe8re automatiquement au Professionnel une perte qui r\xe9sulterait exclusivement d\u2019un manquement imputable \xe0 FOODTECH SOLUTIONS."]},{heading:"26. Avis clients",paragraphs:["Les Clients remplissant les conditions d\xe9finies par Croki peuvent publier un avis relatif \xe0 une Commande.","Le Professionnel peut consulter les avis associ\xe9s \xe0 ses \xe9tablissements et r\xe9pondre lorsqu\u2019une fonctionnalit\xe9 de r\xe9ponse est propos\xe9e.","Le Professionnel ne peut pas modifier la note ou le commentaire d\u2019un Client.","Il peut utiliser le m\xe9canisme pr\xe9vu par Croki pour signaler de mani\xe8re motiv\xe9e un avis qu\u2019il estime illicite, frauduleux ou contraire aux r\xe8gles applicables.","Le Professionnel s\u2019interdit toute pratique destin\xe9e \xe0 produire, acheter, \xe9changer ou manipuler artificiellement des avis ou des notes."]},{heading:"27. R\xe9f\xe9rencement et classement",paragraphs:["Les \xe9tablissements et offres peuvent \xeatre r\xe9f\xe9renc\xe9s et class\xe9s selon plusieurs param\xe8tres utilis\xe9s par Croki.","Les principaux param\xe8tres susceptibles d\u2019influencer le classement comprennent notamment la localisation ou la distance par rapport \xe0 la recherche du Client, les crit\xe8res et filtres s\xe9lectionn\xe9s, l\u2019\xe9tat d\u2019ouverture ou de disponibilit\xe9, la pertinence par rapport \xe0 la recherche et, lorsque cela est utilis\xe9 par le Service, les \xe9valuations disponibles.","L\u2019importance relative de ces param\xe8tres d\xe9pend du contexte de recherche et des choix effectu\xe9s par le Client.","Croki ne divulgue pas le code source, les param\xe8tres techniques permettant de contourner ou manipuler le classement ni les informations dont la divulgation compromettrait la s\xe9curit\xe9 ou l\u2019int\xe9grit\xe9 du Service.","Dans le fonctionnement actuel du Service, le paiement de la commission ordinaire due \xe0 Croki ne permet pas au Professionnel d\u2019acheter une meilleure position dans le classement.","Si Croki introduit ult\xe9rieurement un m\xe9canisme permettant d\u2019influencer le classement contre r\xe9mun\xe9ration, les Conditions Pro et les informations de classement seront mises \xe0 jour avant son utilisation."]},{heading:"28. Acc\xe8s aux donn\xe9es",paragraphs:["Le Professionnel dispose, dans les limites fonctionnelles et l\xe9gales du Service, d\u2019un acc\xe8s aux donn\xe9es n\xe9cessaires \xe0 la gestion de ses propres \xe9tablissements et Commandes.","Cet acc\xe8s peut notamment porter sur les informations de son \xe9tablissement, son Catalogue, les Commandes re\xe7ues, leur statut, les donn\xe9es op\xe9rationnelles n\xe9cessaires \xe0 leur ex\xe9cution, les avis et certaines donn\xe9es ou statistiques relatives \xe0 son activit\xe9.","Le Professionnel n\u2019a pas acc\xe8s aux donn\xe9es non publiques appartenant aux autres Professionnels.","FOODTECH SOLUTIONS dispose des donn\xe9es n\xe9cessaires \xe0 l\u2019exploitation, la s\xe9curit\xe9, la facturation, la conformit\xe9, l\u2019administration et l\u2019am\xe9lioration du Service.","L\u2019acc\xe8s aux donn\xe9es personnelles des Clients est limit\xe9 \xe0 ce qui est n\xe9cessaire pour ex\xe9cuter les Commandes et les obligations respectives des parties.","Les donn\xe9es ne peuvent \xeatre r\xe9utilis\xe9es par le Professionnel \xe0 des fins incompatibles avec la finalit\xe9 pour laquelle elles lui ont \xe9t\xe9 communiqu\xe9es ou en violation de la r\xe9glementation relative aux donn\xe9es personnelles."]},{heading:"29. Donn\xe9es apr\xe8s la fin de la relation",paragraphs:["\xc0 la fin de la relation contractuelle, l\u2019acc\xe8s du Professionnel aux fonctionnalit\xe9s actives de Croki peut prendre fin.","FOODTECH SOLUTIONS peut n\xe9anmoins conserver certaines donn\xe9es lorsque cette conservation est n\xe9cessaire \xe0 la preuve des op\xe9rations, \xe0 la comptabilit\xe9, \xe0 la fiscalit\xe9, \xe0 la pr\xe9vention de la fraude, au traitement des litiges ou au respect d\u2019une obligation l\xe9gale.","Les conditions de conservation des donn\xe9es personnelles sont pr\xe9cis\xe9es dans la Politique de confidentialit\xe9.","Le Professionnel peut demander l\u2019acc\xe8s ou l\u2019export des informations qui lui sont l\xe9galement ou contractuellement accessibles, sous r\xe9serve des droits de tiers, des donn\xe9es personnelles et des obligations de conservation."]},{heading:"30. Prestataires techniques et partage de donn\xe9es",paragraphs:["FOODTECH SOLUTIONS utilise des prestataires techniques n\xe9cessaires au fonctionnement de Croki, notamment pour l\u2019h\xe9bergement, la base de donn\xe9es, le paiement, les communications et certains services cartographiques.","Des donn\xe9es peuvent \xeatre communiqu\xe9es \xe0 ces prestataires lorsque cela est n\xe9cessaire \xe0 la fourniture, \xe0 la s\xe9curit\xe9 ou \xe0 la conformit\xe9 du Service.","FOODTECH SOLUTIONS ne conf\xe8re pas au Professionnel un droit d\u2019acc\xe8s aux donn\xe9es appartenant \xe0 d\u2019autres Professionnels ou \xe0 des utilisateurs lorsque cet acc\xe8s n\u2019est pas n\xe9cessaire \xe0 son activit\xe9 ou serait contraire \xe0 la r\xe9glementation.","Les traitements de donn\xe9es personnelles sont d\xe9crits plus pr\xe9cis\xe9ment dans la Politique de confidentialit\xe9."]},{heading:"31. Absence d\u2019exclusivit\xe9",paragraphs:["Sauf accord \xe9crit particulier express\xe9ment conclu entre FOODTECH SOLUTIONS et le Professionnel, l\u2019utilisation de Croki n\u2019est pas exclusive.","Le Professionnel demeure libre d\u2019exploiter son propre point de vente et d\u2019utiliser d\u2019autres canaux de commande ou plateformes.","Les pr\xe9sentes Conditions n\u2019imposent pas, par elles-m\xeames, au Professionnel de proposer sur Croki les m\xeames prix ou conditions que sur ses autres canaux.","Le Professionnel demeure toutefois tenu de respecter les engagements particuliers qu\u2019il aurait express\xe9ment conclus et la r\xe9glementation applicable \xe0 ses pratiques commerciales."]},{heading:"32. Propri\xe9t\xe9 intellectuelle de Croki",paragraphs:[`La marque ${s.LEGAL_TRADE_NAME}, le logiciel, l\u2019architecture du Service, ses interfaces et les \xe9l\xe9ments prot\xe9g\xe9s cr\xe9\xe9s par ${s.LEGAL_OPERATOR_NAME} restent la propri\xe9t\xe9 de ${s.LEGAL_OPERATOR_NAME} ou de leurs titulaires respectifs.`,"L\u2019utilisation du Service n\u2019accorde au Professionnel qu\u2019un droit personnel, limit\xe9, non exclusif et non transf\xe9rable d\u2019utiliser les fonctionnalit\xe9s de Croki pendant la dur\xe9e de la relation contractuelle.","Le Professionnel ne peut reproduire, extraire, modifier, revendre ou exploiter les \xe9l\xe9ments prot\xe9g\xe9s de Croki en dehors des usages autoris\xe9s par les pr\xe9sentes Conditions ou par la loi."]},{heading:"33. Licence sur les contenus du Professionnel",paragraphs:["Le Professionnel conserve les droits qu\u2019il d\xe9tient sur les contenus qu\u2019il fournit \xe0 Croki.","Il accorde \xe0 FOODTECH SOLUTIONS, pour la dur\xe9e n\xe9cessaire \xe0 l\u2019exploitation du Service, une autorisation non exclusive d\u2019h\xe9berger, reproduire, adapter techniquement, afficher et communiquer ces contenus uniquement dans la mesure n\xe9cessaire \xe0 leur pr\xe9sentation sur Croki, \xe0 la promotion de son \xe9tablissement dans le cadre du Service et au fonctionnement normal de la plateforme.","Le Professionnel garantit disposer des droits n\xe9cessaires pour accorder cette autorisation."]},{heading:"34. Utilisations interdites",paragraphs:["Le Professionnel s\u2019interdit toute utilisation frauduleuse, abusive ou illicite de Croki.","Il est notamment interdit de manipuler artificiellement les commandes, prix, \xe9valuations ou classements ; d\u2019acc\xe9der aux donn\xe9es d\u2019un autre Professionnel ; de contourner les contr\xf4les de s\xe9curit\xe9 ; de cr\xe9er de fausses transactions ; de diffuser un contenu illicite ; ou d\u2019utiliser les donn\xe9es des Clients de mani\xe8re non autoris\xe9e.","Le Professionnel s\u2019interdit \xe9galement d\u2019utiliser Croki pour commercialiser un produit ou exercer une activit\xe9 interdite par la loi ou incompatible avec la finalit\xe9 du Service."]},{heading:"35. Restriction, d\xe9r\xe9f\xe9rencement et suspension",paragraphs:["FOODTECH SOLUTIONS peut restreindre une fonctionnalit\xe9, d\xe9r\xe9f\xe9rencer un contenu ou un \xc9tablissement ou suspendre tout ou partie du Service lorsqu\u2019un motif l\xe9gitime le justifie.","Ces motifs peuvent notamment comprendre une violation des pr\xe9sentes Conditions, une obligation l\xe9gale ou r\xe9glementaire, une information professionnelle non v\xe9rifiable, un risque sanitaire, une fraude, un risque pour les Clients, un d\xe9faut de paiement, un probl\xe8me Stripe emp\xeachant les paiements, un contenu illicite, une atteinte aux droits d\u2019un tiers ou un incident de s\xe9curit\xe9.","La mesure prise doit \xeatre adapt\xe9e \xe0 la nature et \xe0 la gravit\xe9 de la situation lorsque les circonstances le permettent.","Lorsque les r\xe8gles applicables l\u2019exigent, FOODTECH SOLUTIONS communique au Professionnel sur un support durable les motifs de la restriction ou de la suspension avant ou au moment o\xf9 elle prend effet.","Lorsque cela est raisonnablement possible, Croki privil\xe9gie une mesure portant uniquement sur le contenu, l\u2019\xc9tablissement ou la fonctionnalit\xe9 concern\xe9e plut\xf4t qu\u2019une suspension totale du Compte Pro."]},{heading:"36. Mesures urgentes",paragraphs:["FOODTECH SOLUTIONS peut agir sans pr\xe9avis lorsqu\u2019une intervention imm\xe9diate est impos\xe9e par la loi ou n\xe9cessaire pour faire face \xe0 un risque grave ou imminent, notamment concernant la s\xe9curit\xe9 alimentaire, la fraude, la cybers\xe9curit\xe9, les donn\xe9es personnelles, un contenu manifestement illicite ou la s\xe9curit\xe9 des utilisateurs.","Lorsque cela est l\xe9galement possible, le Professionnel re\xe7oit ensuite une information sur la mesure et son motif."]},{heading:"37. R\xe9clamations du Professionnel",paragraphs:["Le Professionnel peut contester une d\xe9cision, signaler un dysfonctionnement ou adresser une r\xe9clamation au moyen du Support Pro.","Le traitement est gratuit pour le Professionnel.","Croki examine les r\xe9clamations de mani\xe8re raisonnable, diligente et proportionn\xe9e au regard de leur nature et de leur complexit\xe9.","La r\xe9clamation peut notamment porter sur une d\xe9cision de restriction, suspension ou d\xe9r\xe9f\xe9rencement, un probl\xe8me technique, une question de facturation ou le fonctionnement du Service.","Le d\xe9p\xf4t d\u2019une r\xe9clamation n\u2019emp\xeache pas FOODTECH SOLUTIONS de maintenir une mesure lorsqu\u2019elle demeure n\xe9cessaire \xe0 la s\xe9curit\xe9, \xe0 la conformit\xe9 ou au fonctionnement du Service."]},{heading:"38. Dur\xe9e de la relation",paragraphs:["Les pr\xe9sentes Conditions Pro prennent effet lorsque le Professionnel les accepte et utilise Croki en qualit\xe9 de Professionnel.","Elles restent applicables pendant toute la dur\xe9e de la relation entre FOODTECH SOLUTIONS et le Professionnel, sous r\xe9serve des dispositions qui, par leur nature, continuent \xe0 produire effet apr\xe8s sa fin."]},{heading:"39. Fin de la relation \xe0 l\u2019initiative du Professionnel",paragraphs:["Le Professionnel peut cesser d\u2019utiliser Croki et demander la fermeture de son Compte Pro.","La cl\xf4ture d\xe9finitive peut \xeatre diff\xe9r\xe9e le temps de terminer ou r\xe9gulariser les Commandes en cours, remboursements, contestations, factures, obligations fiscales ou autres op\xe9rations restant \xe0 traiter.","La cessation de la relation n\u2019efface pas les obligations n\xe9es ant\xe9rieurement \xe0 sa prise d\u2019effet."]},{heading:"40. R\xe9siliation \xe0 l\u2019initiative de FOODTECH SOLUTIONS",paragraphs:["Lorsque FOODTECH SOLUTIONS d\xe9cide de mettre fin \xe0 l\u2019ensemble du service d\u2019interm\xe9diation fourni \xe0 un Professionnel et que le r\xe8glement P2B est applicable, elle communique en principe au Professionnel un expos\xe9 des motifs sur un support durable au moins trente jours avant la prise d\u2019effet de la r\xe9siliation.","Ce d\xe9lai ne s\u2019applique pas lorsqu\u2019une obligation l\xe9gale ou r\xe9glementaire impose une cessation plus rapide, lorsqu\u2019une r\xe9siliation imm\xe9diate est l\xe9galement justifi\xe9e compte tenu des circonstances, ou en cas de violations r\xe9p\xe9t\xe9es permettant l\u2019application des exceptions pr\xe9vues par la r\xe9glementation.","La r\xe9siliation ne prive pas le Professionnel des droits n\xe9s avant sa prise d\u2019effet."]},{heading:"41. Modification des Conditions Pro",paragraphs:["FOODTECH SOLUTIONS peut modifier les pr\xe9sentes Conditions lorsque l\u2019\xe9volution du Service, de son mod\xe8le \xe9conomique, de la s\xe9curit\xe9, de la r\xe9glementation ou de ses fonctionnalit\xe9s le justifie.","Les modifications sont notifi\xe9es au Professionnel sur un support durable avant leur entr\xe9e en vigueur.","Lorsque le r\xe8glement P2B est applicable, le d\xe9lai de pr\xe9avis est raisonnable et proportionn\xe9 et ne peut en principe \xeatre inf\xe9rieur \xe0 quinze jours.","Un d\xe9lai plus long est accord\xe9 lorsque la modification impose au Professionnel des adaptations techniques ou commerciales importantes.","Les exceptions pr\xe9vues par la r\xe9glementation restent applicables, notamment lorsqu\u2019une modification imm\xe9diate est impos\xe9e par une obligation l\xe9gale ou n\xe9cessaire pour r\xe9pondre \xe0 un danger impr\xe9vu et imminent li\xe9 notamment \xe0 la fraude, aux logiciels malveillants, aux violations de donn\xe9es ou \xe0 d\u2019autres risques de cybers\xe9curit\xe9.","Le Professionnel peut mettre fin \xe0 sa relation avec Croki avant l\u2019expiration du d\xe9lai applicable dans les conditions pr\xe9vues par la r\xe9glementation et les pr\xe9sentes Conditions."]},{heading:"42. Confidentialit\xe9",paragraphs:["Chaque partie s\u2019engage \xe0 pr\xe9server les informations non publiques de l\u2019autre partie dont elle prend connaissance dans le cadre de la relation et qui pr\xe9sentent raisonnablement un caract\xe8re confidentiel.","Cette obligation ne concerne pas les informations d\xe9j\xe0 publiques, obtenues licitement aupr\xe8s d\u2019un tiers ou dont la communication est impos\xe9e par la loi ou une autorit\xe9 comp\xe9tente.","Les obligations sp\xe9cifiques relatives aux donn\xe9es personnelles sont r\xe9gies par la Politique de confidentialit\xe9 et la r\xe9glementation applicable."]},{heading:"43. Donn\xe9es personnelles",paragraphs:["Chaque partie respecte les obligations qui lui incombent en mati\xe8re de protection des donn\xe9es personnelles.","FOODTECH SOLUTIONS traite les donn\xe9es n\xe9cessaires \xe0 l\u2019exploitation de Croki conform\xe9ment \xe0 sa Politique de confidentialit\xe9.","Le Professionnel ne peut utiliser les donn\xe9es de Clients auxquelles il acc\xe8de au moyen de Croki que dans la mesure n\xe9cessaire \xe0 l\u2019ex\xe9cution des Commandes, au respect de ses obligations l\xe9gales ou lorsqu\u2019une autre base juridique valable autorise le traitement.","Le Professionnel ne peut notamment pas utiliser automatiquement les coordonn\xe9es d\u2019un Client obtenues pour une Commande afin de lui adresser des communications commerciales ind\xe9pendantes sans disposer d\u2019une base l\xe9gale appropri\xe9e."]},{heading:"44. Coop\xe9ration r\xe9glementaire",paragraphs:["Le Professionnel coop\xe8re avec FOODTECH SOLUTIONS lorsque cette coop\xe9ration est raisonnablement n\xe9cessaire pour permettre \xe0 Croki ou au Professionnel de respecter une obligation l\xe9gale ou r\xe9glementaire li\xe9e \xe0 l\u2019activit\xe9 exerc\xe9e sur la plateforme.","Cette coop\xe9ration peut notamment concerner l\u2019identification du Professionnel, la s\xe9curit\xe9 alimentaire, la protection des consommateurs, la fiscalit\xe9, les demandes d\u2019autorit\xe9s comp\xe9tentes, les contenus illicites, la fraude ou les obligations applicables aux plateformes num\xe9riques.","FOODTECH SOLUTIONS limite les demandes d\u2019informations \xe0 ce qui est pertinent au regard de l\u2019obligation concern\xe9e."]},{heading:"45. Responsabilit\xe9 du Professionnel",paragraphs:["Le Professionnel r\xe9pond des dommages r\xe9sultant des manquements qui lui sont imputables, notamment concernant ses produits, ses informations, sa pr\xe9paration, ses obligations sanitaires, ses contenus ou l\u2019utilisation de son Compte Pro.","Il demeure responsable des actes r\xe9alis\xe9s par les personnes auxquelles il autorise l\u2019acc\xe8s \xe0 son \xe9tablissement ou \xe0 ses outils professionnels.","Cette responsabilit\xe9 s\u2019appr\xe9cie conform\xe9ment aux r\xe8gles l\xe9gales applicables et ne peut avoir pour effet de rendre le Professionnel responsable d\u2019un dommage exclusivement imputable \xe0 FOODTECH SOLUTIONS."]},{heading:"46. Responsabilit\xe9 de FOODTECH SOLUTIONS",paragraphs:[`FOODTECH SOLUTIONS est responsable de l\u2019ex\xe9cution des obligations qui lui incombent au titre de l\u2019exploitation de ${s.LEGAL_TRADE_NAME}.`,"Croki ne garantit pas une disponibilit\xe9 permanente et sans interruption du Service, notamment en cas de maintenance, incident technique, r\xe9seau, prestataire tiers ou op\xe9ration de s\xe9curit\xe9.","FOODTECH SOLUTIONS met en \u0153uvre des moyens raisonnables afin d\u2019assurer le fonctionnement, la disponibilit\xe9 et la s\xe9curit\xe9 de Croki.","Aucune stipulation des pr\xe9sentes Conditions n\u2019exclut une responsabilit\xe9 qui ne peut l\xe9galement \xeatre exclue ou limit\xe9e."]},{heading:"47. Force majeure",paragraphs:["Aucune partie n\u2019est responsable d\u2019un manquement directement caus\xe9 par un \xe9v\xe9nement r\xe9pondant aux conditions l\xe9gales de la force majeure.","La partie concern\xe9e informe l\u2019autre partie dans un d\xe9lai raisonnable lorsque l\u2019\xe9v\xe9nement affecte de mani\xe8re significative l\u2019ex\xe9cution de la relation."]},{heading:"48. Droit applicable",paragraphs:["Les pr\xe9sentes Conditions Pro sont r\xe9gies par le droit fran\xe7ais.","Les parties privil\xe9gient, lorsqu\u2019un diff\xe9rend s\u2019y pr\xeate, une tentative de r\xe9solution amiable avant toute proc\xe9dure judiciaire.","Cette tentative amiable ne prive aucune partie de son droit de prendre une mesure urgente ou conservatoire ni de saisir une juridiction lorsqu\u2019elle l\u2019estime n\xe9cessaire."]},{heading:"49. Litiges entre professionnels",paragraphs:["Les diff\xe9rends relatifs \xe0 l\u2019utilisation de Croki peuvent d\u2019abord \xeatre adress\xe9s au Support Pro afin de rechercher une solution amiable.","Les obligations particuli\xe8res relatives \xe0 un syst\xe8me interne de traitement des plaintes ou \xe0 l\u2019identification de m\xe9diateurs pr\xe9vues par le r\xe8glement europ\xe9en Platform-to-Business sont appliqu\xe9es lorsque FOODTECH SOLUTIONS entre dans leur champ d\u2019application et ne b\xe9n\xe9ficie pas d\u2019une exemption pr\xe9vue par ce r\xe8glement.","\xc0 d\xe9faut de r\xe9solution amiable, le litige rel\xe8ve des juridictions comp\xe9tentes d\xe9termin\xe9es conform\xe9ment aux r\xe8gles l\xe9gales applicables."]},{heading:"50. Contact",paragraphs:[`Exploitant : ${s.LEGAL_OPERATOR_NAME}.`,`Service : ${s.LEGAL_TRADE_NAME}.`,`Si\xe8ge social : ${s.LEGAL_SLOT.registeredOffice}.`,`E-mail : ${s.LEGAL_SLOT.email}.`,`T\xe9l\xe9phone : ${s.LEGAL_SLOT.phone}.`]}]})},1528,[1630,1228]);